        c = new C();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance == 0);
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.Collect(amount) {} catch { return; }
        reverted = false;
        assertTrue(!reverted && address(c).balance == cBalBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}

