contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint depositAmount, uint minSum, uint collectAmount) public payable {
        require(depositAmount <= address(this).balance);
        require(depositAmount > 0);
        c.SetMinSum(minSum);
        c.Deposit{value: depositAmount}();
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        bool reverted;
        c.Collect(collectAmount);
        reverted = false;
        uint balAfter = c.balances(address(this));
        uint ethAfter = address(c).balance;
        if (balBefore < minSum || balBefore < collectAmount) {
            assert(balAfter == balBefore && ethAfter == ethBefore);
        } else {
            assert(balAfter == balBefore - collectAmount && ethBefore - ethAfter == collectAmount);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint depositAmount, uint minSum, uint collectAmount) public payable {
        require(depositAmount <= address(this).balance);
        require(depositAmount > 0);
        c.SetMinSum(minSum);
        c.Deposit{value: depositAmount}();
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        c.Collect(collectAmount);
        uint balAfter = c.balances(address(this));
        uint ethAfter = address(c).balance;
        assert(
            (balBefore < minSum || balBefore < collectAmount)
                ? (balAfter == balBefore && ethAfter == ethBefore)
                : (balAfter == balBefore - collectAmount && ethBefore - ethAfter == collectAmount)
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        // Fresh contract: recorded balance of this contract is 0.
        uint256 beforeBal = c.balances(address(this));
        uint256 contractBefore = address(c).balance;

        bool reverted;
        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = c.balances(address(this));
        uint256 contractAfter = address(c).balance;

        // Since amount > recorded balance (>= MinSum check or amount check fails),
        // Collect must silently do nothing: no revert, no state or Ether change.
        assert(!reverted && afterBal == beforeBal && contractAfter == contractBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _am) public {
        // Fresh c: MinSum is 0, balances[msg.sender] (this contract) is 0,
        // so Collect(_am) only passes the guard for _am == 0.
        require(_am == 0);
        c.SetMinSum(0);
        uint balBefore = address(c).balance;

        // This contract's receive() reverts, so the payout call inside
        // Collect fails and Collect must revert as a whole.
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }

        assert(reverted && address(c).balance == balBefore);
    }

    receive() external payable {
        revert();
    }
}
